import z3

v = [z3.Int(f"v_{i}") for i in range(16)]
s = z3.Solver()

# All labels distinct and in 0..36
s.add(z3.Distinct(v))
for var in v:
    s.add(var >= 0, var <= 36)

# Fix v[0] = 0 to break symmetry
s.add(v[0] == 0)

# Edge differences
edges = []
for g in range(4):
    base = g * 4
    for i in range(4):
        for j in range(i+1, 4):
            edges.append((base + i, base + j))
for g in range(3):
    for i in range(4):
        edges.append((g*4 + i, (g+1)*4 + i))

diffs = []
for (a, b) in edges:
    d = z3.If(v[a] > v[b], v[a] - v[b], v[b] - v[a])
    diffs.append(d)

s.add(z3.Distinct(diffs))
for d in diffs:
    s.add(d >= 1, d <= 36)

# 36 must be adjacent to 0 (vertex 0)
s.add(z3.Or([v[i] == 36 for i in [1,2,3,4]]))

print("Solving with Z3...")
result = s.check()
print("Result:", result)

if result == z3.sat:
    m = s.model()
    sol = [m.evaluate(v[i]).as_long() for i in range(16)]
    print("Solution:", sol)

    # Verify
    edge_diffs = set()
    for g in range(4):
        base = g*4
        for i in range(4):
            for j in range(i+1, 4):
                edge_diffs.add(abs(sol[base+i] - sol[base+j]))
    for g in range(3):
        for i in range(4):
            edge_diffs.add(abs(sol[g*4+i] - sol[(g+1)*4+i]))
    print("Distinct diffs:", len(edge_diffs))
    print("Diffs:", sorted(edge_diffs))
elif result == z3.unsat:
    print("UNSAT")
else:
    print("Unknown")
